
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_m08_so_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_m08_so", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.066819959567455e+00, -1.034734225841100e+00, -9.999579811609400e-01, -9.717565232548725e-01, -9.672781373213067e-01, -9.984062034168659e-01, -1.018575930268839e+00, -9.410942461812517e-01, -1.011511897705248e+00, -9.782005592633930e-01, -6.319605056487230e-01, -3.486764044640977e-01, -2.310368944025217e-01, -1.923973357468892e-01, -2.031551400348687e-01, -1.475883992589578e-01, -7.895672505946433e-02, -3.534112502075993e-02, -7.147931292550964e-03, -7.995172741904787e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


